#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(ggplot2);library(ggthemes)})
r<-'2026/projection-empirical-weight-comparison'
b<-read_csv(file.path(r,'previous_age_schedules.csv'),show_col_types=FALSE) |> filter(case_id=='primary')
n<-read_csv(file.path(r,'deterministic_age_schedules.csv'),show_col_types=FALSE) |> filter(case_id=='primary')
weights<-bind_rows(b |> transmute(age,weight_kg=fishery_weight,Schedule='Previous projection catch'),b |> transmute(age,weight_kg=spawning_weight,Schedule='Previous projection SSB'),b |> transmute(age,weight_kg=fishery_weight2026,Schedule='Fishery input 2026'),n |> transmute(age,weight_kg=fishery_weight,Schedule='Empirical 2020-2024: catch and SSB'))
write_csv(weights,file.path(r,'weight_curve_comparison.csv'))
p<-ggplot(weights,aes(age,weight_kg,color=Schedule,linetype=Schedule,shape=Schedule))+geom_line(linewidth=.7)+geom_point(size=2)+scale_x_continuous(breaks=1:15,labels=c(as.character(1:14),'15+'))+labs(x='Age',y='Weight (kg per fish)',title='Model 26.0 projection weights: empirical five-year mean comparison',subtitle='Equal-year mean of prepared fishery input weights,2020-2024; same mean used for catch and SSB.',caption='2026 fishery age 3 = 0.644 kg; previous projected age 3 = 0.370 kg; empirical mean age 3 = 0.430 kg.\nPopulation weights, fitted starting abundance, M, maturity, selectivity, and recruitment assumptions are preserved.')+theme_few(base_size=12)+theme(legend.position='bottom',legend.title=element_blank(),plot.caption=element_text(hjust=0,size=9))+guides(color=guide_legend(nrow=2),linetype=guide_legend(nrow=2),shape=guide_legend(nrow=2))
ggsave('2026/assets/projection-empirical-weight-curves.png',p,width=11,height=7,dpi=180)
ggsave('2026/tables/projection-empirical-weight-curves.pdf',p,width=11,height=7,device=cairo_pdf)
a<-read_csv(file.path(r,'native_annual_summaries.csv'),show_col_types=FALSE) |> filter(case_id=='primary',Alt==2,metric %in% c('Catch','SSB')) |> mutate(Schedule=recode(weight_case,previous='Previous schedules',empirical_2020_2024='Empirical 2020-2024'),metric=recode(metric,Catch='Catch (kt)',SSB='Female spawning biomass (kt)'))
p<-ggplot(a,aes(Year,mean,color=Schedule,fill=Schedule))+geom_ribbon(aes(ymin=p05,ymax=p95),alpha=.13,color=NA)+geom_line(linewidth=.8)+facet_wrap(~metric,ncol=1,scales='free_y')+scale_color_manual(values=c('Previous schedules'='#333333','Empirical 2020-2024'='#0072B2'))+scale_fill_manual(values=c('Previous schedules'='#333333','Empirical 2020-2024'='#0072B2'))+scale_x_continuous(breaks=seq(2027,2038,1))+labs(x='Year',y=NULL,title='Model 26.0 Alternative 2: projection-weight comparison',subtitle='Fixed catch of 1,375 kt in 2027 and 2028; then maximum ABC. Shared recruitment assumptions and seed.',caption='Lines: spmR means of 1,000 future-recruitment simulations; ribbons: 5th-95th percentiles.\nSSB differences include the changed weight schedule as well as different fishing mortality. This comparison does not refit the population.')+theme_few(base_size=12)+theme(legend.position='bottom',legend.title=element_blank(),plot.caption=element_text(hjust=0,size=9))
ggsave('2026/assets/projection-empirical-weight-trajectories.png',p,width=11,height=8,dpi=180)
ggsave('2026/tables/projection-empirical-weight-trajectories.pdf',p,width=11,height=8,device=cairo_pdf)
